using System;
using System.IO;
using System.Linq;
using System.Drawing;
using System.Diagnostics;
using System.Collections.Generic;
using System.Windows.Forms;
using Microsoft.Win32;
namespace MonitorSlice {
public class MainForm:Form {
 readonly ComboBox monitor=new ComboBox(),keep=new ComboBox();readonly Diagram preview=new Diagram();readonly FlowLayoutPanel choices=new FlowLayoutPanel();readonly Label status=new Label(),help=new Label(),driverStatus=new Label();
 readonly Button start=new Button(),stop=new Button(),merge=new Button(),edit=new Button(),undo=new Button(),install=new Button(),repair=new Button(),removeDriver=new Button();
 readonly VirtualSession session=new VirtualSession();List<Region> regions=Layouts.Create("grid");readonly Stack<List<Region>> history=new Stack<List<Region>>();Screen target;bool hotkey,busy,closing;
 public MainForm(){AutoScaleMode=AutoScaleMode.None;Text="Monitor Slice · 가상 모니터 분할";Font=new Font("맑은 고딕",10);BackColor=Color.FromArgb(245,248,253);Size=new Size(1100,850);MinimumSize=new Size(1030,760);StartPosition=FormStartPosition.CenterScreen;
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(22),ColumnCount=1,RowCount=8};Controls.Add(root);
  root.RowStyles.Add(new RowStyle(SizeType.Absolute,60));root.RowStyles.Add(new RowStyle(SizeType.Absolute,62));root.RowStyles.Add(new RowStyle(SizeType.Absolute,92));root.RowStyles.Add(new RowStyle(SizeType.Absolute,76));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));root.RowStyles.Add(new RowStyle(SizeType.Absolute,56));root.RowStyles.Add(new RowStyle(SizeType.Absolute,60));
  root.Controls.Add(new Label{Text="모니터 하나를 여러 개의 바탕화면으로",Dock=DockStyle.Fill,Font=new Font(Font.FontFamily,19,FontStyle.Bold)},0,0);
  var selection=new FlowLayoutPanel{Dock=DockStyle.Fill};selection.Controls.Add(new Label{Text="① 분할할 모니터",AutoSize=true,Margin=new Padding(0,9,12,0)});monitor.DropDownStyle=ComboBoxStyle.DropDownList;monitor.Width=670;selection.Controls.Add(monitor);root.Controls.Add(selection,0,1);
  choices.Dock=DockStyle.Fill;for(int i=0;i<Layouts.Keys.Length;i++){var b=new LayoutButton(Layouts.Keys[i],Layouts.Names[i]);b.Click+=delegate(object sender,EventArgs e){history.Push(regions);regions=Layouts.Create(((LayoutButton)sender).Mode);preview.Editing=false;preview.Selected.Clear();UpdateUi();if(session.Active)StartSplit();};choices.Controls.Add(b);}root.Controls.Add(choices,0,2);
  var tools=new FlowLayoutPanel{Dock=DockStyle.Fill};edit.Text="직접 영역 합치기";edit.Size=new Size(180,33);edit.Click+=delegate{preview.Editing=!preview.Editing;preview.Selected.Clear();UpdateUi();};tools.Controls.Add(edit);keep.DropDownStyle=ComboBoxStyle.DropDownList;keep.FormattingEnabled=true;keep.Format+=delegate(object sender,ListControlConvertEventArgs e){e.Value="바탕화면 "+(char)('A'+(int)e.ListItem);};keep.Width=135;tools.Controls.Add(keep);merge.Text="선택 영역 합치기";merge.Size=new Size(165,33);merge.Click+=delegate{try{var next=Layouts.Merge(regions,preview.Selected,(int)keep.SelectedItem);history.Push(regions);regions=next;preview.Selected.Clear();UpdateUi();if(session.Active)StartSplit();}catch(Exception ex){SetStatus(ex.Message,true);}};tools.Controls.Add(merge);undo.Text="↶ 되돌리기";undo.Size=new Size(135,33);undo.Click+=delegate{if(history.Count>0){regions=history.Pop();preview.Selected.Clear();UpdateUi();if(session.Active)StartSplit();}};tools.Controls.Add(undo);help.Size=new Size(980,31);tools.Controls.Add(help);root.Controls.Add(tools,0,3);
  preview.Dock=DockStyle.Fill;preview.Titles=new[]{"Windows 바탕화면","Windows 바탕화면","Windows 바탕화면","Windows 바탕화면"};preview.RegionClick=delegate(int slot){if(!preview.Editing)return;if(!preview.Selected.Add(slot))preview.Selected.Remove(slot);UpdateUi();};root.Controls.Add(preview,0,4);
  root.Controls.Add(new Label{Text="프로그램 등록 없이 사용합니다. 각 칸은 Windows의 별도 가상 모니터가 됩니다.",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft},0,5);
  var actions=new FlowLayoutPanel{Dock=DockStyle.Fill};start.Text="분할 시작";start.Size=new Size(180,38);start.BackColor=Color.RoyalBlue;start.ForeColor=Color.White;start.Click+=delegate{StartSplit();};actions.Controls.Add(start);stop.Text="분할 종료 · 원래대로";stop.Size=new Size(210,38);stop.Click+=delegate{StopSplit();};actions.Controls.Add(stop);install.Text="설치 · 자동 설정";install.Size=new Size(200,38);install.Click+=delegate{Setup("install");};actions.Controls.Add(install);repair.Text="설치 복구";repair.Size=new Size(110,38);repair.Click+=delegate{Setup("recover");};actions.Controls.Add(repair);removeDriver.Text="드라이버 제거";removeDriver.Size=new Size(170,38);removeDriver.Click+=delegate{Setup("remove");};actions.Controls.Add(removeDriver);root.Controls.Add(actions,0,6);
  var bottom=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2};driverStatus.Dock=status.Dock=DockStyle.Fill;bottom.Controls.Add(driverStatus);bottom.Controls.Add(status);root.Controls.Add(bottom,0,7);
  Load+=delegate{try{SetupFlow.RecoverDesktop();session.Recover();}catch(Exception ex){SetStatus("이전 디스플레이 복구 실패: "+ex.Message,true);}LoadMonitors();hotkey=Native.RegisterHotKey(Handle,10,0x4003,0x7A);UpdateUi();if(!hotkey)SetStatus("Ctrl+Alt+F11 단축키 등록 실패. 시작 전에 다른 앱의 단축키를 확인하세요.",true);};
  FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;return;}closing=true;try{session.Stop();}catch(Exception ex){e.Cancel=true;closing=false;SetStatus("복원 실패: "+ex.Message,true);}if(!e.Cancel&&hotkey)Native.UnregisterHotKey(Handle,10);};
  SystemEvents.DisplaySettingsChanged+=DisplayChanged;FormClosed+=delegate{SystemEvents.DisplaySettingsChanged-=DisplayChanged;};UpdateUi();
 }
 void LoadMonitors(){var old=monitor.SelectedItem as ScreenItem;var virtualNames=new HashSet<string>(Displays.Virtual().Select(d=>d.Name));monitor.Items.Clear();int n=0;foreach(var s in Screen.AllScreens)if(!virtualNames.Contains(s.DeviceName))monitor.Items.Add(new ScreenItem{Screen=s,Number=++n});if(monitor.Items.Count>0){monitor.SelectedIndex=0;if(old!=null)for(int i=0;i<monitor.Items.Count;i++)if(((ScreenItem)monitor.Items[i]).Screen.DeviceName==old.Screen.DeviceName)monitor.SelectedIndex=i;}}
 void DisplayChanged(object sender,EventArgs e){if(IsDisposed||!IsHandleCreated||closing)return;BeginInvoke((Action)delegate{if(busy||session.Changing||closing)return;if(session.Active&&target!=null){var current=Screen.AllScreens.FirstOrDefault(s=>s.DeviceName==target.DeviceName);if(current==null||current.Bounds!=session.OutputBounds){StopSplit();SetStatus("실제 모니터 구성이 변경되어 원래 화면으로 복원했습니다.",false);}}else{LoadMonitors();UpdateUi();}});}
 void Setup(string operation){if(busy||session.Active)return;busy=true;SetStatus("Windows 승인 후 "+(operation=="install"?"설치와 자동 설정":operation=="remove"?"가상 모니터 제거":"설치 복구")+"를 진행합니다. 완료될 때까지 기다려 주세요.",false);UpdateUi();try{SetupFlow.Run(operation);LoadMonitors();if(operation=="install"&&!VirtualSession.Ready)throw new Exception("Windows를 다시 시작한 뒤 설치 · 자동 설정을 다시 눌러 주세요.");SetStatus(operation=="install"?"설치와 독립 모니터 4개 설정 완료. 분할 시작을 누르세요.":operation=="remove"?"이 앱이 설치한 가상 모니터를 제거했습니다.":"설치 기록과 기존 화면 복구 완료. 필요하면 설치 · 자동 설정을 눌러 주세요.",false);}catch(System.ComponentModel.Win32Exception ex){SetStatus(ex.NativeErrorCode==1223?"Windows 승인을 취소했습니다. 기존 화면을 복원했습니다.":ex.Message,true);}catch(Exception ex){SetStatus(ex.Message,true);}finally{busy=false;UpdateUi();}}
 void StartSplit(){if(busy)return;if(!hotkey){SetStatus("긴급 복원 단축키 Ctrl+Alt+F11을 등록한 뒤 시작할 수 있습니다.",true);return;}if(!VirtualSession.Ready){SetStatus("실제 가상 모니터를 생성하려면 서명된 디스플레이 드라이버 설치가 필요합니다.",true);return;}if(monitor.SelectedItem==null)return;busy=true;UpdateUi();try{target=((ScreenItem)monitor.SelectedItem).Screen;session.Start(target.Bounds,regions,true);if(WindowCarry.Failed>0){SetStatus("분할 실행 중 · 일부 창을 옮기지 못했습니다. 해당 창을 직접 이동해 주세요.",true);return;}SetStatus("분할 실행 중 · 기존 내용은 왼쪽 위 칸으로 이동 · Ctrl+Alt+F11: 원래대로",false);}catch(Exception ex){SetStatus("분할 시작 실패: "+ex.Message,true);}finally{busy=false;UpdateUi();}}
 public void StopSplit(){if(busy)return;busy=true;try{session.Stop();SetStatus(WindowCarry.Failed>0?"화면과 아이콘 복원 완료 · 일부 프로그램 창은 직접 위치를 확인해 주세요.":"분할 종료 · 기존 화면·아이콘·창 위치를 복원했습니다.",WindowCarry.Failed>0);}catch(Exception ex){SetStatus("복원 실패: "+ex.Message,true);}finally{busy=false;UpdateUi();}}
 public void SetStatus(string text,bool error){status.Text=text;status.ForeColor=error?Color.Firebrick:Color.FromArgb(52,76,108);}
 static string Shape(List<Region> rs){return string.Join(";",rs.Select(r=>r.X+","+r.Y+","+r.W+","+r.H).OrderBy(s=>s));}
 void UpdateUi(){preview.Regions=regions;preview.Invalidate();var prior=keep.SelectedItem;keep.Items.Clear();foreach(var slot in preview.Selected.OrderBy(s=>s))keep.Items.Add(slot);if(keep.Items.Count>0){keep.SelectedIndex=0;if(prior!=null&&keep.Items.Contains(prior))keep.SelectedItem=prior;}merge.Enabled=false;if(preview.Selected.Count>1)try{Layouts.Merge(regions,preview.Selected,(int)keep.SelectedItem);merge.Enabled=!busy;}catch{}keep.Visible=merge.Visible=preview.Editing;edit.Text=preview.Editing?"편집 완료":"직접 영역 합치기";help.Text=preview.Editing?"이웃한 영역을 눌러 선택하세요. 합쳐진 영역에 유지할 바탕화면을 선택합니다.":"② 배치 그림 선택 → ③ 분할 시작 · 창을 최대화하면 해당 칸만 채웁니다.";undo.Enabled=history.Count>0&&!busy;monitor.Enabled=!session.Active&&!busy;start.Enabled=!busy;start.Text=session.Active?"현재 배치 적용":"분할 시작";stop.Enabled=session.Active&&!busy;install.Enabled=repair.Enabled=removeDriver.Enabled=!session.Active&&!busy;driverStatus.Text=VirtualSession.Ready?"가상 모니터 드라이버: 준비됨":"가상 모니터 드라이버: 설치 필요";foreach(LayoutButton b in choices.Controls){b.Enabled=!busy;b.Chosen=Shape(Layouts.Create(b.Mode))==Shape(regions);b.Invalidate();}}
 protected override void WndProc(ref Message m){if(m.Msg==0x312&&m.WParam.ToInt32()==10){StopSplit();Show();WindowState=FormWindowState.Normal;Activate();}base.WndProc(ref m);}
}
public class ScreenItem {public Screen Screen;public int Number;public override string ToString(){var b=Screen.Bounds;return "모니터 "+Number+(Screen.Primary?" · 주 화면":"")+" · "+b.Width+"×"+b.Height+" · "+(b.Width<b.Height?"세로":"가로")+" · 위치 "+b.X+", "+b.Y;}}
}
